INSERT INTO kb.regla(codigo,tipo,conector,hecho_id,valor_conclusion,confianza,ruta,texto,fuente) VALUES ('RH-14','derivacion','Y',(SELECT id FROM kb.hecho WHERE nombre='ram_baja'),'verdadero','n/a',NULL,'SI ram_total_gb < 8 GB ENTONCES ram_baja = verdadero.','Ampliación v2 (criterio de diseño, pendiente de validar por el experto)');
INSERT INTO kb.regla_condicion VALUES ((SELECT id FROM kb.regla WHERE codigo='RH-14'),1,(SELECT id FROM kb.hecho WHERE nombre='ram_total_gb'),'<','8');
INSERT INTO kb.regla(codigo,tipo,conector,hecho_id,valor_conclusion,confianza,ruta,texto,fuente) VALUES ('RH-15','derivacion','O',(SELECT id FROM kb.hecho WHERE nombre='ram_configuracion_desigual'),'verdadero','n/a',NULL,'SI ram_modulos < 2 O ram_capacidades_distintas > 1 O ram_frecuencias_distintas > 1 ENTONCES ram_configuracion_desigual = verdadero.','Ampliación v2 (criterio de diseño, pendiente de validar por el experto)');
INSERT INTO kb.regla_condicion VALUES ((SELECT id FROM kb.regla WHERE codigo='RH-15'),1,(SELECT id FROM kb.hecho WHERE nombre='ram_modulos'),'<','2');
INSERT INTO kb.regla_condicion VALUES ((SELECT id FROM kb.regla WHERE codigo='RH-15'),2,(SELECT id FROM kb.hecho WHERE nombre='ram_capacidades_distintas'),'>','1');
INSERT INTO kb.regla_condicion VALUES ((SELECT id FROM kb.regla WHERE codigo='RH-15'),3,(SELECT id FROM kb.hecho WHERE nombre='ram_frecuencias_distintas'),'>','1');
INSERT INTO kb.regla(codigo,tipo,conector,hecho_id,valor_conclusion,confianza,ruta,texto,fuente) VALUES ('RH-16','derivacion','Y',(SELECT id FROM kb.hecho WHERE nombre='cpu_basica'),'verdadero','n/a',NULL,'SI cpu_nucleos <= 2 ENTONCES cpu_basica = verdadero.','Ampliación v2 (criterio de diseño, pendiente de validar por el experto)');
INSERT INTO kb.regla_condicion VALUES ((SELECT id FROM kb.regla WHERE codigo='RH-16'),1,(SELECT id FROM kb.hecho WHERE nombre='cpu_nucleos'),'<=','2');
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P26','Memoria RAM en configuración desigual','Hardware','media','La memoria está en un solo módulo o los módulos tienen capacidades o frecuencias distintas, por lo que trabaja en un solo canal o a la frecuencia del módulo más lento.',ARRAY['Si tu equipo lo permite, instala dos módulos iguales para activar el doble canal.','Revisa en la BIOS que la memoria funcione a su frecuencia nominal (perfil XMP o EXPO).','Evita mezclar módulos de distinta capacidad o frecuencia: el sistema usará la velocidad del más lento.'],'Ampliación v2 (criterio de diseño, pendiente de validar por el experto)',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P27','Sistema instalado en disco duro mecánico','Hardware','alta','El sistema operativo está en un disco duro mecánico (HDD), mucho más lento que un SSD al iniciar el equipo y abrir programas.',ARRAY['Cambia el disco del sistema por un SSD y clona o reinstala el sistema.','Mientras tanto, desactiva los programas de inicio y desfragmenta el disco.','Deja los archivos pesados en el HDD y usa el SSD para el sistema y tus programas.'],'Ampliación v2 (criterio de diseño, pendiente de validar por el experto)',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P28','Gráficos integrados limitados','Hardware','media','El equipo no tiene tarjeta gráfica dedicada y la gráfica integrada se satura con tareas visuales exigentes.',ARRAY['Baja la calidad gráfica o la resolución en los programas y juegos.','Cierra programas que usan mucho video, como el navegador con muchas pestañas.','Considera una tarjeta gráfica dedicada si tu equipo lo permite.'],'Ampliación v2 (criterio de diseño, pendiente de validar por el experto)',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P29','Procesador con pocos núcleos','Hardware','media','El procesador tiene solo uno o dos núcleos y se satura con los programas actuales.',ARRAY['Cierra los programas en segundo plano y desactiva los de inicio.','Usa programas más ligeros, por ejemplo un navegador con pocas pestañas.','Evalúa actualizar el procesador o el equipo.'],'Ampliación v2 (criterio de diseño, pendiente de validar por el experto)',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P30','Programas consumiendo mucha memoria','Rendimiento y software','media','Aunque el equipo tiene memoria suficiente, algunos programas (o una fuga de memoria) están ocupando casi toda la RAM.',ARRAY['Abre el Administrador de tareas, ordena por Memoria y cierra el programa que más consume.','Reinicia el equipo y comprueba si el problema vuelve con un programa en particular.','Revisa las extensiones del navegador y los programas de inicio, y analiza el equipo con el antivirus.'],'Ampliación v2 (criterio de diseño, pendiente de validar por el experto)',false);
INSERT INTO kb.regla(codigo,tipo,conector,hipotesis_id,confianza,ruta,texto,fuente) VALUES ('R-P26','diagnostico','Y',(SELECT id FROM kb.hipotesis WHERE codigo='P26'),'media',NULL,'SI sintoma_principal = lentitud Y recurso_saturado = ninguno Y ram_configuracion_desigual = verdadero ENTONCES diagnóstico = (ver P26) CON confianza = media.','Ampliación v2 (criterio de diseño, pendiente de validar por el experto)');
INSERT INTO kb.regla_condicion VALUES ((SELECT id FROM kb.regla WHERE codigo='R-P26'),1,(SELECT id FROM kb.hecho WHERE nombre='sintoma_principal'),'=','lentitud');
INSERT INTO kb.regla_condicion VALUES ((SELECT id FROM kb.regla WHERE codigo='R-P26'),2,(SELECT id FROM kb.hecho WHERE nombre='recurso_saturado'),'=','ninguno');
INSERT INTO kb.regla_condicion VALUES ((SELECT id FROM kb.regla WHERE codigo='R-P26'),3,(SELECT id FROM kb.hecho WHERE nombre='ram_configuracion_desigual'),'=','verdadero');
