-- Ampliación v2: los componentes registrados del equipo (RAM por módulos, discos, GPU, CPU) pasan a ser evidencia del motor.
-- Hechos del equipo: los numéricos y los de tipo sí/no los calcula la aplicación al leer el equipo; los demás los derivan las reglas RH-14 a RH-16.
-- Reglas existentes que ahora también consideran el equipo
UPDATE kb.regla SET texto = REPLACE(texto,' ENTONCES',' Y gpu_dedicada = verdadero ENTONCES') WHERE codigo='R-P02';
UPDATE kb.regla SET texto = REPLACE(texto,' ENTONCES',' Y ram_baja = verdadero ENTONCES') WHERE codigo='R-P07';
-- Preguntas por disco cuando el equipo tiene varios
UPDATE kb.hecho SET ambito='disco', pregunta_varios='¿Cuáles de tus discos tienen menos de 10 % de espacio libre?' WHERE nombre='disco_lleno';
UPDATE kb.hecho SET ambito='disco', pregunta_varios='¿En cuáles de tus discos hay archivos corruptos o errores de lectura o escritura?' WHERE nombre='disco_con_errores';
